 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    counts = Counter(x for row in grid for x in row)
    # Foreground rectangles are the repeated colors; isolated speckles are noise.
    colors = {c for c, n in counts.items() if c != bg and n >= 10}
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color in colors:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                            seen.add((yy,xx)); q.append((yy,xx))
                # Components belonging to a large object; reconstruct its clean rectangle.
                if len(cells) >= 5:
                    r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
                    c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
                    for y in range(r0, r1+1):
                        for x in range(c0, c1+1):
                            out[y][x] = color
    return out
